class DisjointSet {
    vector<int> rank, parent, size;

public:
    DisjointSet(int n) {
        rank.resize(n + 1, 0);
        parent.resize(n + 1);
        size.resize(n + 1);
        for (int i = 0; i <= n; i++) {
            parent[i] = i;
            size[i] = 1;
        }
    }

    // Find the ultimate parent of a node (with path compression)
    int findUPar(int node) {
        if (node == parent[node])
            return node;
        return parent[node] = findUPar(parent[node]);
    }

    // Union by size
    void unionBySize(int u, int v) {
        int ulpU = findUPar(u);
        int ulpV = findUPar(v);
        if (ulpU == ulpV) return;
        if (size[ulpU] < size[ulpV]) {
            parent[ulpU] = ulpV;
            size[ulpV] += size[ulpU];
        } else {
            parent[ulpV] = ulpU;
            size[ulpU] += size[ulpV];
        }
    }
};

// Function to find minimum operations required
int minConnect(vector<vector<int>>& adj) {
    int n = adj.size();
    DisjointSet ds(n);
    int extra = 0;

    // Traverse all links in adjacency list
    for (int u = 0; u < n; u++) {
        for (int v : adj[u]) {

            // To avoid processing duplicate edges 
            if (u < v) {

                // If both hospitals are already connected,
                //mark this link as extra
                if (ds.findUPar(u) == ds.findUPar(v))
                    extra++;
                else
                    ds.unionBySize(u, v);
            }
        }
    }

    // Count disconnected components
    int components = 0;
    for (int i = 0; i < n; i++) {
       if(ds.findUPar(i)==i){
           components++;
       }
    }

    // If enough extra links exist to connect all components
    if (extra >= components - 1)
        return components - 1;
    else
        return -1;
}

